SET NAMES utf8mb4;
SET time_zone = '+03:30';
START TRANSACTION;

-- پاک‌سازی اجرای قبلی (پروژه‌ها، تسک‌ها، چت و همکاران با CASCADE حذف می‌شوند)
DELETE t FROM tasks t JOIN users u ON u.id = t.user_id WHERE u.mobile IN ('09991867331', '09991867332', '09991867333', '09991867334', '09991867335', '09991867336');
DELETE FROM users WHERE mobile IN ('09991867331', '09991867332', '09991867333', '09991867334', '09991867335', '09991867336');

