-- خلاصه
SELECT u.mobile, CONCAT(u.first_name, ' ', u.last_name) AS name,
  (SELECT COUNT(*) FROM tasks t WHERE t.assignee_id = u.id) AS tasks,
  (SELECT COUNT(*) FROM tasks t WHERE t.assignee_id = u.id AND t.is_completed = 1) AS done
FROM users u WHERE u.mobile IN ('09991867331', '09991867332', '09991867333', '09991867334', '09991867335', '09991867336') ORDER BY u.mobile;
